CREATE TABLE IF NOT EXISTS public.managers (
    category_name_level_1 TEXT PRIMARY KEY,
    manager TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS public.orders (
    amount DECIMAL NOT NULL,
    category_name_level_1 TEXT NOT NULL,
    category_name_level_2 TEXT NOT NULL,
    category_name_level_3 TEXT NOT NULL,
    model_name TEXT NOT NULL,
    order_buyer_region_name TEXT NOT NULL,
    order_buyer_region_population_group TEXT NOT NULL,
    order_delivery_region_province_name TEXT NOT NULL,
    order_buyer_region_province_polygon TEXT NOT NULL,
    order_creation_date TIMESTAMPTZ NOT NULL,
    order_delivery_attribute_delivery_service_name TEXT NOT NULL,
    order_delivery_datetime TIMESTAMPTZ NOT NULL,
    order_id TEXT PRIMARY KEY,
    order_multiorder_order_count INTEGER NOT NULL,
    order_order_status TEXT NOT NULL,
    order_payment_method TEXT NOT NULL,
    order_payment_type TEXT NOT NULL,
    order_platform TEXT NOT NULL,
    quantity INTEGER NOT NULL,
    sku_is_seasonal_flag BOOLEAN NOT NULL,
    user_id TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS public.plan_managers (
    date TIMESTAMPTZ NOT NULL,
    manager TEXT NOT NULL,
    plan INTEGER NOT NULL
);
ALTER TABLE public.plan_managers DROP CONSTRAINT IF EXISTS plan_managers_pkey;
ALTER TABLE public.plan_managers ADD PRIMARY KEY (date,manager,plan);

CREATE TABLE IF NOT EXISTS public.geo_polygons (
    order_buyer_region_province_name TEXT PRIMARY KEY,
    order_buyer_region_province_polygon TEXT NOT NULL
);

